CREATE SEQUENCE IF NOT EXISTS order_number_seq START WITH 1001;
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY,order_number bigint NOT NULL UNIQUE DEFAULT nextval('order_number_seq'),status text NOT NULL CHECK(status IN ('pending','paid','failed','cancelled')),customer jsonb NOT NULL,items jsonb NOT NULL,shipping_method text NOT NULL,subtotal_agorot integer NOT NULL,shipping_agorot integer NOT NULL,total_agorot integer NOT NULL,sumit_payment_id text UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),paid_at timestamptz,customer_email_sent_at timestamptz,merchant_email_sent_at timestamptz,email_last_error text);
CREATE INDEX IF NOT EXISTS orders_status_created_idx ON orders(status,created_at DESC);
